    ms' = MS (mkR (Z_to_bv 64 0xa3560) (Z_to_bv 64 (C - 112)) gp tp t0' t1' t2' (Z_to_bv 64 C) (Z_to_bv 64 INST)
                  (Z_to_bv 64 cache) (Z_to_bv 64 INST) (Z_to_bv 64 24) (Z_to_bv 64 b) a4' a5' a6' a7'
                  (Z_to_bv 64 2364568) (Z_to_bv 64 2365192) (Z_to_bv 64 b) (Z_to_bv 64 (2^37)) s6' s7' s8' s9'
                  s10 s11 t3' t4' t5' t6')
